import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    s = h.sum()
    if s <= 0:
        return 1e9
    return 2.0 * len(h) * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    N = 200
    i = np.arange(N) + 0.5
    h0 = 1.0 - 0.55 * np.sin(2.0 * np.pi * i / N)
    h0 = np.maximum(h0, 1e-6)
    h0 = h0 / h0.sum()

    # If start is provided and has a better C, use it as a warm start (resampled to N).
    if start is not None:
        s = np.asarray(start, dtype=float).ravel()
        if s.size > 0 and np.all(np.isfinite(s)) and s.sum() > 0:
            if s.size == N:
                cand = np.maximum(s, 0.0)
                if cand.sum() > 0:
                    cand = cand / cand.sum()
                    if _C(cand) < _C(h0):
                        h0 = cand
            else:
                # resample to N via linear interpolation
                xs = (np.arange(s.size) + 0.5) / s.size
                xt = (np.arange(N) + 0.5) / N
                cand = np.interp(xt, xs, s)
                cand = np.maximum(cand, 0.0)
                if cand.sum() > 0:
                    cand = cand / cand.sum()
                    if _C(cand) < _C(h0):
                        h0 = cand

    def obj(h):
        return _C(h)

    def obj_grad(h):
        # numerical gradient via finite differences on C
        eps = 1e-7
        g = np.zeros_like(h)
        base = _C(h)
        for k in range(len(h)):
            hp = h.copy()
            hp[k] += eps
            g[k] = (_C(hp) - base) / eps
        return g

    cons = [{'type': 'eq', 'fun': lambda h: h.sum() - 1.0,
             'jac': lambda h: np.ones_like(h)}]
    bounds = [(0.0, None)] * N

    best_h = h0.copy()
    best_C = _C(h0)

    # Try SLSQP with a time guard; fall back gracefully.
    try:
        remaining = budget_seconds * 0.85
        # Use a callback to stop if out of time.
        class Timeout(Exception):
            pass

        def cb(hk):
            if time.process_time() - t0 > remaining:
                raise Timeout()

        res = minimize(obj, h0, method='SLSQP', bounds=bounds,
                       constraints=cons, callback=cb,
                       options={'maxiter': 500, 'ftol': 1e-12})
        if res.x is not None and np.all(np.isfinite(res.x)):
            hh = np.maximum(res.x, 0.0)
            if hh.sum() > 0:
                hh = hh / hh.sum()
                c = _C(hh)
                if c < best_C:
                    best_h, best_C = hh, c
    except Exception:
        pass

    # A quick local polish: coordinate-wise multiplicative jitter search.
    rng = np.random.default_rng(12345)
    h = best_h.copy()
    cur = best_C
    step = 0.05
    while time.process_time() - t0 < budget_seconds * 0.95:
        improved = False
        for _ in range(20):
            k = rng.integers(0, N)
            trial = h.copy()
            trial[k] *= (1.0 + step * rng.standard_normal())
            trial = np.maximum(trial, 0.0)
            if trial.sum() <= 0:
                continue
            trial /= trial.sum()
            c = _C(trial)
            if c < cur:
                h, cur = trial, c
                improved = True
        if not improved:
            step *= 0.5
            if step < 1e-6:
                break

    return h

