    s1 = np.sin(2 * np.pi * u)
    c1 = np.cos(2 * np.pi * u)
    s2 = np.sin(4 * np.pi * u)
    c2 = np.cos(4 * np.pi * u)

    def make(c):
        return 1.0 + c[0] * s1 + c[1] * c1 + c[2] * s2 + c[3] * c2

    def obj(c):
        h = make(c)
        pen = 1e6 * np.sum(np.minimum(h, 0.0) ** 2)
        return _C(np.maximum(h, 0.0)) + pen

    x0 = np.array([-0.55, 0.0, 0.0, 0.0])
    best_h = make(x0)
    best_C = _C(np.maximum(best_h, 0.0))

    # Also consider start
    if start is not None:
        hs = np.asarray(start, dtype=float)
        if hs.size > 0 and hs.sum() > 0:
            cs = _C(hs)
            if cs < best_C:
                best_C = cs
                best_h = hs.copy()

    # Nelder-Mead with time guard
