    # Choose initial h
    if start is not None:
        h0 = np.asarray(start, dtype=float).ravel()
        if h0.size != N or h0.sum() <= 0 or not np.all(np.isfinite(h0)):
            h0 = _p0005_result()
    else:
        h0 = _p0005_result()

    h0 = np.clip(h0, 0.0, None)
