import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    N = len(h)
    return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    N = 1600
    nblk = 8

    def build(params):
        # params: 7 logits for widths (softmax), 8 heights
        logits = params[:nblk - 1]
        c = np.clip(params[nblk - 1:], 0.0, None)
        e = np.exp(logits - logits.max())
        last = np.exp(-logits.max())
        w = np.concatenate([e, [last]])
        w = w / w.sum()
        edges = np.round(np.concatenate([[0.0], np.cumsum(w)]) * N).astype(int)
        edges = np.clip(edges, 0, N)
        # ensure monotone nondecreasing
        for i in range(1, len(edges)):
            if edges[i] < edges[i - 1]:
                edges[i] = edges[i - 1]
        edges[-1] = N
        counts = np.diff(edges)
        h = np.repeat(c, counts)
        if h.size != N:
            # fallback pad/truncate
            if h.size < N:
                h = np.concatenate([h, np.full(N - h.size, c[-1])])
            else:
                h = h[:N]
        return h, w, c

    def obj(params):
        h, _, _ = build(params)
        return _C(h)

    # Initialization from start
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0:
            if s.size >= N:
                s = s[:N]
            idx = np.linspace(0, s.size, nblk + 1).astype(int)
            init_c = np.array([s[idx[i]:max(idx[i] + 1, idx[i + 1])].mean()
                               for i in range(nblk)])
        else:
            init_c = np.ones(nblk)
    else:
        init_c = np.ones(nblk)
    init_c = np.clip(init_c, 1e-6, None)
    init_logits = np.zeros(nblk - 1)
    x0 = np.concatenate([init_logits, init_c])

    best_val = np.inf
    best_params = x0.copy()

    # Nelder-Mead on 15 params
    try:
        res = minimize(obj, x0, method='Nelder-Mead',
                       options={'maxiter': 4000, 'xatol': 1e-6, 'fatol': 1e-10,
                                'adaptive': True})
        if res.fun < best_val:
            best_val = res.fun
            best_params = res.x.copy()
    except Exception:
        pass

    # Polish heights at fixed widths with L-BFGS-B
    if time.process_time() - t0 < budget_seconds * 0.75:
        _, w, _ = build(best_params)
        edges = np.round(np.concatenate([[0.0], np.cumsum(w)]) * N).astype(int)
        edges = np.clip(edges, 0, N)
        for i in range(1, len(edges)):
            if edges[i] < edges[i - 1]:
                edges[i] = edges[i - 1]
        edges[-1] = N
        counts = np.diff(edges)

        def obj_h(c):
            c = np.clip(np.asarray(c, dtype=float), 0.0, None)
            h = np.repeat(c, counts)
            if h.size != N:
                if h.size < N:
                    h = np.concatenate([h, np.full(N - h.size, c[-1])])
                else:
                    h = h[:N]
            return _C(h)

        c0 = np.clip(best_params[nblk - 1:], 1e-6, None)
        try:
            res2 = minimize(obj_h, c0, method='L-BFGS-B',
                            bounds=[(0.0, None)] * nblk,
                            options={'maxiter': 2000, 'ftol': 1e-15, 'gtol': 1e-12})
            if res2.fun < best_val:
                best_val = res2.fun
                best_params = np.concatenate([best_params[:nblk - 1],
                                              np.clip(res2.x, 0.0, None)])
        except Exception:
            pass

    h, w, c = build(best_params)
    C_h = _C(h)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C(s) < C_h:
            print("kept start, C =", _C(s))
            return s

    print("8-varblock C =", C_h, "w =", w, "c =", c)
    return h

