import numpy as np
import time
from scipy.optimize import minimize
from scipy.special import logsumexp


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    N = len(h)
    return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    N = 1600
    nblk = 16

    # block assignment: nblk blocks partition [0, N)
    def make_h(params):
        # params: [15 logits for widths, 16 heights]
        wlogits = params[:nblk - 1]
        heights = np.clip(params[nblk - 1:], 0.0, None)
        # softmax widths
        w = np.exp(wlogits - np.max(wlogits))
        w = np.concatenate([[1.0], w])  # first block reference
        w = w / w.sum()
        # cumulative edges
        edges = np.floor(np.cumsum(w) * N).astype(int)
        edges[-1] = N
        edges[0] = 0
        # ensure monotone
        for i in range(1, len(edges)):
            if edges[i] < edges[i - 1]:
                edges[i] = edges[i - 1]
        h = np.empty(N)
        for i in range(nblk):
            a, b = edges[i], edges[i + 1]
            if b > a:
                h[a:b] = heights[i]
        return h

    def exact_obj(params):
        return _C(make_h(params))

    def lse_obj_factory(tau):
        def obj(params):
            h = make_h(params)
            s = h.sum()
            if s <= 0:
                return 1e30
            conv = np.convolve(h, h)
            lse = tau * logsumexp(conv / tau)
            return 2.0 * N * lse / (s * s)
        return obj

    # Initial params from start
    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size >= N:
            s = s[:N]
        elif s.size > 0:
            s = np.interp(np.linspace(0, 1, N), np.linspace(0, 1, s.size), s)
        else:
            s = np.ones(N)
    else:
        s = np.ones(N)

    # average into 16 equal bins for initial heights
    idx = np.linspace(0, N, nblk + 1).astype(int)
    init_h = np.array([s[idx[i]:max(idx[i] + 1, idx[i + 1])].mean()
                       for i in range(nblk)])
    init_h = np.clip(init_h, 1e-6, None)
    init_wlogits = np.zeros(nblk - 1)
    init = np.concatenate([init_wlogits, init_h])

    bounds = [(None, None)] * (nblk - 1) + [(0.0, None)] * nblk

    taus = [1e-2, 3e-3, 1e-3, 3e-4, 1e-4, 3e-5, 1e-5]
    p = init.copy()
    for tau in taus:
        if time.process_time() - t0 > budget_seconds * 0.55:
            break
        try:
            res = minimize(lse_obj_factory(tau), p, method='L-BFGS-B',
                           bounds=bounds,
                           options={'maxiter': 400, 'ftol': 1e-14, 'gtol': 1e-10})
            p = res.x.copy()
        except Exception:
            break

    best_p = p.copy()
    best_val = exact_obj(p)
    # exact polish
    if time.process_time() - t0 < budget_seconds * 0.9:
        try:
            res = minimize(exact_obj, p, method='L-BFGS-B', bounds=bounds,
                           options={'maxiter': 2000, 'ftol': 1e-15, 'gtol': 1e-12})
            if res.fun < best_val:
                best_val = res.fun
                best_p = res.x.copy()
        except Exception:
            pass

    h = make_h(best_p)

    if start is not None:
        s = np.asarray(start, dtype=float)
        if s.size > 0 and s.sum() > 0 and _C(s) < _C(h):
            print("kept start, C =", _C(s))
            return s

    print("varwidth C =", _C(h), "params =", best_p)
    return h

