import time
from scipy.optimize import minimize


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    N = len(h)
    return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()
    N = 1600
    M = N // 2

    def make_h(c):
        return np.clip(np.asarray(c, dtype=float), 0.0, None)

    def sym_h(x):
        x = np.clip(np.asarray(x, dtype=float), 0.0, None)
        return np.concatenate([x, x[::-1]])

    def exact_obj_sym(x):
        return _C(sym_h(x))

    def mirror_grad(g_h):
        # g_h is gradient wrt full h (length N); reduce to x (length M)
        return g_h[:M] + g_h[N - M:][::-1]

    def lp_obj_grad_factory(p):
        def fg(x):
            h = sym_h(x)
            s = h.sum()
            if s <= 0:
                return 1e30, np.zeros_like(x)
            conv = np.convolve(h, h)
            cp = np.power(conv, p)
            scp = cp.sum()
            if scp <= 0:
                return 1e30, np.zeros_like(x)
            norm = scp ** (1.0 / p)
            val = 2.0 * N * norm / (s * s)
            w = np.power(conv, p - 1) / (scp ** (1.0 - 1.0 / p))
            g_h = 2.0 * np.convolve(w, h[::-1])[len(h) - 1:2 * len(h) - 1]
            grad_h = 2.0 * N / (s * s) * g_h - 4.0 * N * norm / (s ** 3)
            return val, mirror_grad(grad_h)
        return fg

    def lse_obj_grad_factory(tau):
        def fg(x):
            h = sym_h(x)
            s = h.sum()
            if s <= 0:
                return 1e30, np.zeros_like(x)
            conv = np.convolve(h, h)
            m = conv.max()
            e = np.exp((conv - m) / tau)
            se = e.sum()
            lse = m + tau * np.log(se)
            val = 2.0 * N * lse / (s * s)
            w = e / se
            g_h = 2.0 * np.convolve(w, h[::-1])[len(h) - 1:2 * len(h) - 1]
            grad_h = 2.0 * N / (s * s) * g_h - 4.0 * N * lse / (s ** 3)
            return val, mirror_grad(grad_h)
        return fg

    def topk_obj_grad_factory(tau, K):
        def fg(x):
            h = sym_h(x)
            s = h.sum()
            if s <= 0:
                return 1e30, np.zeros_like(x)
            conv = np.convolve(h, h)
            n = conv.size
            Kk = min(K, n)
            idx = np.argpartition(conv, n - Kk)[n - Kk:]
            m = conv[idx].max()
            e = np.exp((conv[idx] - m) / tau)
            se = e.sum()
            lse = m + tau * np.log(se)
            val = 2.0 * N * lse / (s * s)
            w = np.zeros(n)
            w[idx] = e / se
            g_h = 2.0 * np.convolve(w, h[::-1])[len(h) - 1:2 * len(h) - 1]
            grad_h = 2.0 * N / (s * s) * g_h - 4.0 * N * lse / (s ** 3)
