            x_s = np.linspace(0, 1, s.size)
            x_n = np.linspace(0, 1, N)
            init = np.interp(x_n, x_s, s)
        else:
            init = np.ones(N)
    else:
        init = np.ones(N)

    # Symmetrize the full profile, then take first half as x.
    init = 0.5 * (init + init[::-1])
    x_init = np.clip(init[:M], 1e-6, None)

    bounds = [(0.0, None)] * M

    best_x = x_init.copy()
    best_val = _C(sym_h(best_x))
    if ref is not None and ref_C < best_val:
