    ps = [16, 32, 64, 128, 256, 512, 1024, 2048]
    xx = np.clip(best_x, 1e-6, None)
    for p in ps:
        if time.process_time() - t0 > budget_seconds * 0.30:
            break
        try:
            res = minimize(lp_obj_grad_factory(p), np.clip(xx, 1e-6, None),
                           jac=True, method='L-BFGS-B', bounds=bounds,
                           options={'maxiter': 300, 'ftol': 1e-15, 'gtol': 1e-11})
            xx = np.clip(res.x, 0.0, None)
            v = _C(sym_h(xx))
            if v < best_val:
                best_val = v
                best_x = xx.copy()
        except Exception:
            break

    # Phase 2: logsumexp homotopy.
    taus = [1e-5, 3e-6, 1e-6, 3e-7, 1e-7, 3e-8, 1e-8, 3e-9, 1e-9]
    xx = np.clip(best_x, 1e-6, None)
    for tau in taus:
        if time.process_time() - t0 > budget_seconds * 0.50:
            break
        try:
            res = minimize(lse_obj_grad_factory(tau), np.clip(xx, 1e-6, None),
                           jac=True, method='L-BFGS-B', bounds=bounds,
                           options={'maxiter': 400, 'ftol': 1e-16, 'gtol': 1e-12})
            xx = np.clip(res.x, 0.0, None)
            v = _C(sym_h(xx))
            if v < best_val:
                best_val = v
                best_x = xx.copy()
        except Exception:
            break

    # Phase 3: exact-C polish on x.
    try:
        res = minimize(exact_obj_sym, np.clip(best_x, 1e-6, None),
                       method='L-BFGS-B', bounds=bounds,
                       options={'maxiter': 2000, 'ftol': 1e-15, 'gtol': 1e-12})
        val = res.fun
        cand = np.clip(res.x, 0.0, None)
        if val < best_val:
            best_val = val
            best_x = cand
    except Exception:
        pass

    # Phase 4: second deeper Lp/lse cycle.
    ps2 = [64, 256, 1024, 4096, 8192]
    xx = np.clip(best_x, 1e-6, None)
    for p in ps2:
        if time.process_time() - t0 > budget_seconds * 0.68:
            break
        try:
            res = minimize(lp_obj_grad_factory(p), np.clip(xx, 1e-6, None),
                           jac=True, method='L-BFGS-B', bounds=bounds,
                           options={'maxiter': 300, 'ftol': 1e-15, 'gtol': 1e-11})
            xx = np.clip(res.x, 0.0, None)
            v = _C(sym_h(xx))
            if v < best_val:
                best_val = v
                best_x = xx.copy()
        except Exception:
            break

    taus2 = [3e-8, 1e-8, 3e-9, 1e-9, 3e-10]
    xx = np.clip(best_x, 1e-6, None)
    for tau in taus2:
        if time.process_time() - t0 > budget_seconds * 0.82:
            break
        try:
            res = minimize(lse_obj_grad_factory(tau), np.clip(xx, 1e-6, None),
                           jac=True, method='L-BFGS-B', bounds=bounds,
                           options={'maxiter': 400, 'ftol': 1e-16, 'gtol': 1e-12})
            xx = np.clip(res.x, 0.0, None)
            v = _C(sym_h(xx))
            if v < best_val:
                best_val = v
                best_x = xx.copy()
        except Exception:
            break

    # Phase 5: top-K lse stage on x.
    if time.process_time() - t0 < budget_seconds * 0.85:
        xx = np.clip(best_x, 1e-12, None)
        for tau in [1e-9, 3e-10, 1e-10]:
            if time.process_time() - t0 > budget_seconds * 0.85:
                break
            try:
                res = minimize(topk_obj_grad_factory(tau, 2), np.clip(xx, 1e-12, None),
                               jac=True, method='L-BFGS-B', bounds=bounds,
                               options={'maxiter': 300, 'ftol': 1e-16, 'gtol': 1e-13})
                xx = np.clip(res.x, 0.0, None)
                v = _C(sym_h(xx))
                if v < best_val:
                    best_val = v
                    best_x = xx.copy()
            except Exception:
                break

    # Phase 6: final exact-C polish.
    if time.process_time() - t0 < budget_seconds * 0.88:
        try:
            res = minimize(exact_obj_sym, np.clip(best_x, 1e-12, None),
                           method='L-BFGS-B', bounds=bounds,
                           options={'maxiter': 1000, 'ftol': 1e-16, 'gtol': 1e-13})
            val = res.fun
            cand = np.clip(res.x, 0.0, None)
            if val < best_val:
                best_val = val
                best_x = cand
        except Exception:
            pass

    h = sym_h(best_x)

    if ref is not None and ref_C <= _C(h):
        print("kept start, C =", ref_C)
        return ref

    print("symmetric lp+lse+topK+exact C =", _C(h))
    return h

import numpy as np
import time
from scipy.optimize import minimize


def _C(h):
    h = np.asarray(h, dtype=float)
    s = h.sum()
    if s <= 0:
        return np.inf
    N = len(h)
    return 2.0 * N * np.max(np.convolve(h, h)) / (s * s)


def construct(budget_seconds, start):
    t0 = time.process_time()

    # Base result: use start if given, else fall back to a simple profile.
    if start is not None:
        base = np.clip(np.asarray(start, dtype=float), 0.0, None)
        if base.size == 0 or base.sum() <= 0:
            base = np.ones(1600)
    else:
        base = np.ones(1600)

    N = len(base)
    best_h = base.copy()
    best_val = _C(best_h)
    bounds = [(0.0, None)] * N

    def exact_obj(c):
        return _C(np.clip(np.asarray(c, dtype=float), 0.0, None))

    # Find zero/positive boundaries.
    pos = base > 0
    boundaries = []
    for i in range(1, N):
        if pos[i] != pos[i - 1]:
            boundaries.append(i)
            if len(boundaries) >= 10:
                break

    print("boundaries found:", len(boundaries), "base C =", best_val)

    # For each boundary, try moving it one step and polish with L-BFGS-B.
    for bi, b in enumerate(boundaries):
        if time.process_time() - t0 > budget_seconds * 0.85:
            break
        cand = base.copy()
        if cand[b] > 0:
            cand[b] = 0.0
        else:
            cand[b] = 1e-6
        try:
            res = minimize(exact_obj, np.clip(cand, 1e-12, None),
                           method='L-BFGS-B', bounds=bounds,
                           options={'maxiter': 80, 'ftol': 1e-15, 'gtol': 1e-12})
            h_new = np.clip(res.x, 0.0, None)
            if h_new.sum() > 0:
                v = _C(h_new)
                if v < best_val:
                    best_val = v
                    best_h = h_new.copy()
                    print("boundary move", bi, "at", b, "C =", v)
        except Exception:
            continue

    print("final C =", _C(best_h))
    return best_h
